package com.jmu.text2scpi.voice;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.concurrent.atomic.AtomicLong;
public final class ConversationFlowTest {
 @Test public void linkedWakeRejectsShortInitialConsonantNearMiss(){assertNull(WakePronunciation.display(WakePronunciation.LINKED,new float[]{1.04f,1.12f,1.6f,1.64f}));assertEquals("小欧小欧",WakePronunciation.display(WakePronunciation.LINKED,new float[]{1,1.16f,1.48f,1.56f}));}
 @Test public void linkedWakeNeedsTwoSyllablesWithPlausibleDuration(){assertEquals("小欧小欧",WakePronunciation.display(WakePronunciation.LINKED,new float[]{.32f,.52f,.72f,.88f}));assertNull(WakePronunciation.display(WakePronunciation.LINKED,new float[]{0,.08f,.16f,.28f}));assertNull(WakePronunciation.display(WakePronunciation.LINKED,new float[]{0,.2f,2,2.2f}));assertNull(WakePronunciation.display(WakePronunciation.LINKED,new float[]{}));assertEquals("Hey OWON",WakePronunciation.display("Hey_OWON",null));assertEquals("小欧小欧",WakePronunciation.display("小欧小欧",null));}
 @Test public void wakeWhileListeningStartsOneNewAcknowledgement(){VoiceTurnFlow f=new VoiceTurnFlow();f.manual();assertTrue(f.begin());long ticket=f.wake();assertTrue(ticket>0);assertEquals(0,f.wake());assertFalse(f.begin());assertTrue(f.finishWake(ticket));assertTrue(f.begin());}
 @Test public void noisePunctuationCannotStartADeviceRequest(){assertFalse(new SpeechTextResult("。","。",true,0).hasSpokenContent());assertFalse(new SpeechTextResult("..."," ？！",true,0).hasSpokenContent());assertTrue(new SpeechTextResult("查询时基","查询时基",true,0).hasSpokenContent());assertTrue(new SpeechTextResult("scale 200 mV","scale 200 mV",true,0).hasSpokenContent());}
 @Test public void wakeWaitsForOneReplyBeforeCapturing(){VoiceTurnFlow f=new VoiceTurnFlow();long id=f.wake();assertTrue(id>0);assertEquals(0,f.wake());assertFalse(f.begin());f.suppress();assertTrue(f.finishWake(id));assertFalse(f.finishWake(id));assertTrue(f.begin());}
 @Test public void pauseCancelsLateWakeReply(){VoiceTurnFlow f=new VoiceTurnFlow();long id=f.wake();f.discard();assertFalse(f.finishWake(id));assertTrue(f.idle());}
 @Test public void manualInputCancelsLateWakeReply(){VoiceTurnFlow f=new VoiceTurnFlow();long id=f.wake();f.manual();assertFalse(f.finishWake(id));assertTrue(f.begin());}
 @Test public void serviceMustHandleResultBeforeNextTurn(){VoiceTurnFlow f=new VoiceTurnFlow();f.manual();assertTrue(f.begin());f.recognizing();f.posted();assertFalse(f.idle());f.handled();assertTrue(f.idle());}
 @Test public void staleResultCannotClearNewManualTurn(){VoiceTurnFlow f=new VoiceTurnFlow();f.manual();f.begin();f.recognizing();f.posted();f.manual();f.handled();assertEquals(VoiceTurnFlow.Phase.ARMING,f.phase());}
 @Test public void playbackDiscardsOldCaptureButNotWakeHandshake(){VoiceTurnFlow f=new VoiceTurnFlow();f.manual();f.begin();f.suppress();assertTrue(f.idle());long ticket=f.wake();f.suppress();assertTrue(f.finishWake(ticket));}
 @Test public void continuousRequiresEveryIdleCondition(){assertTrue(ListeningPolicy.mayRearm(true,true,true,true,false,false,false,false,false,false));assertFalse(ListeningPolicy.mayRearm(false,true,true,true,false,false,false,false,false,false));assertFalse(ListeningPolicy.mayRearm(true,false,true,true,false,false,false,false,false,false));assertFalse(ListeningPolicy.mayRearm(true,true,false,true,false,false,false,false,false,false));assertFalse(ListeningPolicy.mayRearm(true,true,true,false,false,false,false,false,false,false));for(int block=0;block<6;block++){boolean[] b=new boolean[6];b[block]=true;assertFalse(ListeningPolicy.mayRearm(true,true,true,true,b[0],b[1],b[2],b[3],b[4],b[5]));}}
 @Test public void playbackTailPreventsImmediateSelfRecording(){AtomicLong time=new AtomicLong();PlaybackInputGate gate=new PlaybackInputGate(time::get);gate.block();time.set(9999);assertTrue(gate.blocked());gate.release();time.addAndGet(199);assertTrue(gate.blocked());time.incrementAndGet();assertFalse(gate.blocked());}
 @Test public void quietWakeBoostIsBoundedAndDoesNotMutateAsrSamples(){WakeInputLevel gain=new WakeInputLevel();float[] input=new float[512];java.util.Arrays.fill(input,.003f);float[] boosted=null;for(int i=0;i<100;i++)boosted=gain.apply(input);assertTrue(boosted[0]>.003f);assertTrue(boosted[0]<=.01201f);assertEquals(.003f,input[0],0);}
 @Test public void silenceCannotBecomeSpeech(){WakeInputLevel gain=new WakeInputLevel();for(float v:gain.apply(new float[512]))assertEquals(0,v,0);}
 @Test public void scopeLanguageRecognizesOnlyKnownValues(){assertEquals("en",ScopeLanguage.parse("ENGLISH\n"));assertEquals("zh",ScopeLanguage.parse("SIMPLIFIEDCHINESE"));assertEquals("zh",ScopeLanguage.parse("Traditional Chinese"));assertNull(ScopeLanguage.parse("ERROR"));assertNull(ScopeLanguage.parse("JAPANESE"));}
}
